(53, 37, 15, 'شاركنا خبرتك', '🌿 أهلًا بكم في «شاركنا خبرتك» 🌿\r\n\r\nهنا كل تجربة لها قيمة، وكل معلومة مفيدة تستحق أن تُشارك.\r\nاحكِ لنا عن تجربة مررت بها، معلومة تعلمتها، مشكلة وجدت لها حلًا، أو نصيحة تتمنى لو عرفتها من قبل.\r\n\r\n💡 ربما ما تعتبره أمرًا بسيطًا، يكون سببًا في مساعدة شخص آخر.\r\n\r\nشاركوا تجاربكم، استفيدوا من تجارب الآخرين، ولنجعل من المجموعة مساحة حقيقية للتعلم وتبادل الخبرات. 🤍\r\n\r\nما الخبرة التي اكتسبتها في حياتك وتتمنى أن يستفيد منها الآخرون؟\r\n#شاركنا_خبرتك #خبرة_تفيد #نتعلم_من_بعض', 0, 0, NULL, NULL, '2026-09-21 01:25:53', '2026-09-21 01:25:53'),
(54, 37, 13, '.', NULL, 0, 0, NULL, NULL, '2026-09-27 09:46:49', '2026-09-27 09:46:49'),
(55, 37, 15, 'شاركنا خبرتك 📚🔍', 'لكل تجربة درس، ولكل موقف حكاية، ولكل شخص خبرة تستحق أن تُروى.\nانضم إلى صفحة «شاركنا خبرتك» وشاركنا ما تعلمته، لنصنع معًا مساحة نتبادل فيها الخبرات والأفكار ونفيد بعضنا البعض. 🌷\n\nشاركنا خبرتك... فربما يحتاجها شخص أكثر مما تتخيل.', 0, 0, NULL, NULL, '2026-09-27 09:48:44', '2026-09-27 09:48:44'),
(56, 431, 15, '.', 'أجمل ما في الإنسان قلبٌ يرحم، ونفسٌ تعفو، ويدٌ تصنع الخير.', 0, 0, NULL, NULL, '2026-10-03 02:57:12', '2026-10-03 02:57:12'),
(100, 116321, 3, 'صورة في المجموعة', NULL, 1, 0, 'image', NULL, '2017-01-15 11:37:45', '2017-01-15 11:37:45'),
(101, 116321, 3, 'قم بطرح موضوع او فيديو او صور لها قيمة في مختلف المجالات داخل جروب مسابقة حكماء العالم وادعو اصدقائك للمشاركة في موضوعك و الاعجاب بة ا و التعليق علية ', 'قم بطرح موضوع او فيديو او صور لها قيمة في مختلف المجالات داخل جروب مسابقة حكماء العالم وادعو اصدقائك للمشاركة في موضوعك و الاعجاب بة ا و التعليق علية اكثر الموضيع لها قيمة و لاقت اهتمام اكتر من الاعضاء سوف تربح احد الجوائز القيمة', 6, 0, NULL, NULL, '2017-01-15 11:38:49', '2017-01-15 11:38:49'),
(135, 116326, 3, 'شاركنا رأيك\\nمن المسؤول عن انهيار التربية\\n1_ الأسرة\\n2_الإعلام\\n3_المدرسة\\n4_ المجتمع\\nو ما هى الحلول المقترحة من وجهة نظرك لخلق جيل واع وذو أخلاق حس', 'شاركنا رأيك\\nمن المسؤول عن انهيار التربية\\n1_ الأسرة\\n2_الإعلام\\n3_المدرسة\\n4_ المجتمع\\nو ما هى الحلول المقترحة من وجهة نظرك لخلق جيل واع وذو أخلاق حسنة .', 1, 0, NULL, NULL, '2017-01-19 13:54:25', '2017-01-19 13:54:25'),
(164, 116365, 3, 'ما هي أسباب تأخر الشباب في الزواج وما هي الحلول التي يمكن ان تساعد في حل هذه المشكلة ؟', 'ما هي أسباب تأخر الشباب في الزواج وما هي الحلول التي يمكن ان تساعد في حل هذه المشكلة ؟', 1, 0, NULL, NULL, '2017-01-23 15:44:39', '2017-01-23 15:44:39'),
(167, 86, 3, 'ما هو سبب في تتطور العالم الي هذه الدرجة', 'ما هو سبب في تتطور العالم الي هذه الدرجة', 3, 0, NULL, NULL, '2017-01-23 21:04:33', '2017-01-23 21:04:33'),
(191, 92, 3, 'إنشاء جروب علي شبكات التواصل الإجتماعي لسيدات كل منطقة أو حي ، بما أن شبكات التواصل أصبحت أقرب وسيلة للتواصل بين الناس\\nالهدف من هذا الجروب تجميع السي', 'إنشاء جروب علي شبكات التواصل الإجتماعي لسيدات كل منطقة أو حي ، بما أن شبكات التواصل أصبحت أقرب وسيلة للتواصل بين الناس\\nالهدف من هذا الجروب تجميع السيدات لإستطلاع ظروف المحتاجين والفقراء للوصول لهم بحكم قربهم أو سكنهم وكيفية مواجهة ظروفهم المعيشية الصعبة من خلال تكاتف أهل الخير بالحي أو المنطقة وهذا بمساعدة كل ربة منزل بما تستطيع من مأكل أو ملبس أو مبلغ شهري إستطاعت توفيره من المنزل ، الهدف من هذا الجروب الوصول للعائلات المتعففة التي لا تستطيع الجمعيات أو الدولة الوصول لهم ومواجهة ظروفهم المعيشية\\nوإيضا شعور كل ربة المنزل بدور جديد لها خارج المنزل والهدف أيضا أن يشعر كل فئات المجتمع بمشاكل البعض ، بالتكاتف أكثر في كل مكان ، و إيضا لمواجهة ومحاربة الغلاء بطريقة تحمل كل المشاعر الإنسانية', 2, 0, NULL, NULL, '2017-01-27 17:54:24', '2017-01-27 17:54:24'),
(195, 116365, 3, 'تأثر الشباب بالغرب هل هو شئ سلبي ام ايجابي ؟', 'تأثر الشباب بالغرب هل هو شئ سلبي ام ايجابي ؟', 2, 0, NULL, NULL, '2017-01-29 15:23:56', '2017-01-29 15:23:56'),
(198, 116367, 3, 'السلام عليكم \\nاريد ان اسال الادارة ماهي المواضيع التي تريدون منا مناقشتها ماهي مجالاتها\\nوهل يشترط لها مساحة معينة او عدد كلمات\\nوماهو الموعد الاخير ', 'السلام عليكم \\nاريد ان اسال الادارة ماهي المواضيع التي تريدون منا مناقشتها ماهي مجالاتها\\nوهل يشترط لها مساحة معينة او عدد كلمات\\nوماهو الموعد الاخير للمسابقة\\n', 2, 0, NULL, NULL, '2017-01-29 16:46:28', '2017-01-29 16:46:28'),
(202, 94, 3, 'أسباب البطالة تختلف من بلد لآخر، وكل دولة لها طرق خاصّة في مواجهة هذه المشكلة فهل السبب الرئيسي هو الاعتماد على التكنولوجيا والآلات بدلاً من الأيدي ال', 'أسباب البطالة تختلف من بلد لآخر، وكل دولة لها طرق خاصّة في مواجهة هذه المشكلة فهل السبب الرئيسي هو الاعتماد على التكنولوجيا والآلات بدلاً من الأيدي البشرية ، أم هناك أسباب أخرى؟\\n', 3, 0, 'image', NULL, '2017-01-29 20:03:03', '2017-01-29 20:03:03'),
(693, 16, 3, 'اين المسئول عن هذه الازمة\\n', 'اين المسئول عن هذه الازمة\\n', 3, 0, NULL, NULL, '2017-02-12 12:13:02', '2017-02-12 12:13:02'),
(694, 16, 3, '7 سلع مهمة تأثرت بارتفاع الدولار أمام الجنيه\\nالذهب\\nالحديد\\nالأدوية\\nالملابس\\nالسيارات\\nالأجهزة المعمرة\\nالالكترونيات', '7 سلع مهمة تأثرت بارتفاع الدولار أمام الجنيه\\nالذهب\\nالحديد\\nالأدوية\\nالملابس\\nالسيارات\\nالأجهزة المعمرة\\nالالكترونيات', 3, 0, NULL, NULL, '2017-02-12 12:23:24', '2017-02-12 12:23:24'),
(698, 116365, 3, 'لماذا يرى الرجل زوجته اقل جمالا من الاخريات ..؟', 'لماذا يرى الرجل زوجته اقل جمالا من الاخريات ..؟', 1, 0, NULL, NULL, '2017-02-12 16:01:34', '2017-02-12 16:01:34'),
(827, 86, 3, 'كيف يمكن تخلص من القمامة الموجودة في الفضاء حول الارض؟\\nكانو يريدون ان يضربو نووي ولكنهم خافوا ان تاثر على الارض وفي احتباس الحراري \\nاريد جواب ممتاز ', 'كيف يمكن تخلص من القمامة الموجودة في الفضاء حول الارض؟\\nكانو يريدون ان يضربو نووي ولكنهم خافوا ان تاثر على الارض وفي احتباس الحراري \\nاريد جواب ممتاز وجيد واعجابات وشكرا ;) &lt;3', 1, 0, NULL, NULL, '2017-02-13 14:18:01', '2017-02-13 14:18:01'),
(828, 86, 3, 'ما هو سبب في تتطور دول الغرب  اكثر من دول العرب مع على انا العرب اذكا من دول الغرب ؟ &lt;3', 'ما هو سبب في تتطور دول الغرب  اكثر من دول العرب مع على انا العرب اذكا من دول الغرب ؟ &lt;3', 1, 0, NULL, NULL, '2017-02-13 14:22:57', '2017-02-13 14:22:57'),
(830, 116367, 3, 'هل أصبحت المنابر وسيلة للتكسب والاستجداء؟!\\n\\nهل وصل بنا الحال يا شعبنا الأردني الأبي ،أن نستجدي ونتسول حق الحياة من على منبر رسول الله - صلى الله علي', 'هل أصبحت المنابر وسيلة للتكسب والاستجداء؟!\\n\\nهل وصل بنا الحال يا شعبنا الأردني الأبي ،أن نستجدي ونتسول حق الحياة من على منبر رسول الله - صلى الله عليه وسلم &ndash; ؟ وهل أصبح طرق الأبواب من لوازم ديننا الحنيف؟وهل هذا ما يستحقه شعب النشامى؟!\\nلا تسقني ماءَ الحياة ِ بذلة ٍ بل فاسقني بالعزَّ كاس الحنظل\\nماءُ الحياة ِ بذلة ٍ كجهنم وجهنم بالعزَّ أطيبُ منزل ؟!\\nوهل تردي الأوضاع الاقتصادية هو المشكلة؟لا وألف لا ،إن المشكلة التي نعاني منها هو الفساد الذي ينخر في جسد الوطن ،فمتى وجدنا الحق واتبعناه ،عاد اقتصادنا قويا منيعا ، أمّا هكذا ،فما نحن إلا أرضية يلعب عليها الفاسدون ،وما دماؤنا إلا وديعة عندهم لن يردوها إلينا إلا بعد أن يجهزوا علينا.\\nوليسمح لي فضيلة شيخنا &quot;أحمد هليل&quot; - حفظه الله - أنه ما كان له أن يوقع نفسه بمأزق لا يحسد عليه ،لأن هذا ليس من مهمته.\\nوإنما هذا من مهمة الدبلوماسية الخارجية الأردنية ،والتي فشلت فشلا ذريعا في مواجهة القضايا المصرية ،وعلى رأسها القضية الاقتصادية ،وكسب ودِّ الإخوة الخليجيين وإقناعهم ،بتقديم يد العون المساعدة لإنقاذ الاقتصاد الأردني من أزمته الطاحنة،ويظهر ذلك من خلال التباين بين مضمون وأهداف السياسة الخارجية التي لم تصل إلى الحد الأدنى من التنسيق ،وتقديم المصلحة الوطنية العليا على المصالح الذاتية ،والتعامل مع تلك الأهداف العليا بشيء من نكران الذات ،الأمر الذي أدى إلى ما نحن عليه من ترد خطير في الأوضاع الاقتصادية.\\nفقد أدى ضعف السياسة الخارجية ،الذي يعتبر من أهم ركائز العمل الدبلوماسي ،إلى ضعف الاهتمام بقضايانا المصرية ،وعلى رأسها القضية الاقتصادية ،فلم تعد هذه القضايا محط اهتمام الدول الخليجية ،نتيجة تلاشي الإحساس بالهمِّ العربي المشترك ،لانعدام الثقة.\\nوتتسم الدبلوماسية الأردنية ،بأنها دبلوماسية غامضة غير واضحة المعالم ،والسبب في ذلك تراجع الدور الدبلوماسي والسياسي الأردني ،نتيجة ضعف الجهاز الدبلوماسي ، والتناقض بين الموقفين السياسي الرسمي والشعبي ،فالنظام السياسي القائم على ما يقوم به من مواقف ،أو ما يتخذه من سياسات على المستويين الخارجي والداخلي ،ليس له صلة بما يريده الشعب ،حيث ينعكس هذا الضعف السياسي على المستوى الخارجي ،كما ينعكس على المستوى الداخلي.\\nكما أن الدبلوماسية الأردنية ،تفتقر إلى وجود دبلوماسية وقائية ،للوقاية من أي مشكلة وإدارتها وتسويتها قبل وقوعها ،من خلال برنامج عمل ،لمعالجة الأزمات التي قد يتعرض لها الأردن ، للحيلولة دون استفحال الأزمات وتفاقمها.\\nكما تفتقر إلى مهارة التفاوض وإلى الشفافية ،حيث تفتقر إلى المصداقية ،ولا تعكس الصورة الحقيقية والموضوعية لكثير من القضايا المطروحة ،وعلى رأسها الانضمام إلى مجلس التعاون الخليجي ،وكسب ود الأخوة الخليجيين في تقديم مساعدات مالية للأردن ،والملف السوري.\\nوبالتالي ،كيف يمكن لدبلوماسية غير واضحة المعالم ،أن تكون قوية وفاعلة ؟.\\nلهذا ،لا بد من توحيد المواقف المتناقضة على المستويين الداخلي والخارجي ،للخروج بدبلوماسية فاعلة على المستوى الخارجي.\\nوأعزو ذلك كله ،إلى قصور الإرادة السياسية ،وعدم وجود دبلوماسية متميزة ،تتماشى مع طبيعة المرحلة بكل مستوياتها ،لتنهي واقع الانحدار السياسي والاقتصادي الذي وصلنا إليه ،والذي هو نتاج طبيعي ووليد شرعي ،للخلل البنيوي في النظام السياسي الأردني ،وعجزه عن بناء مؤسسات فاعلة ،نتيجة الازدواجية والافتقار إلى صلة الوصل المؤسساتي \\n\\n\\n', 3, 0, NULL, NULL, '2017-02-13 18:32:21', '2017-02-13 18:32:21'),
(1108, 94, 3, 'الشباب هم عماد الأمة وقوتها ولهم الدور الكبير في نهضة الأمة وتقدم المجتمع, ويجب أن نولي شبابنا الرعاية اللازمة لحمايتهم من الفساد والانحراف ولابد أن ن', 'الشباب هم عماد الأمة وقوتها ولهم الدور الكبير في نهضة الأمة وتقدم المجتمع, ويجب أن نولي شبابنا الرعاية اللازمة لحمايتهم من الفساد والانحراف ولابد أن نفسح لهم المجال ليأخذوا دورهم في نهضة الأمة وتقدم المجتمع..\\nماهي أهم العوامل المسببة لانحراف الشباب؟\\n', 2, 0, 'image', NULL, '2017-02-16 15:44:10', '2017-02-16 15:44:10'),
