(206191, 97547, 2, 'شكر من رئيس تركيا لشيخ تميم والشعب القطري لوقوفه بجانب تركيا', 'شكر من رئيس تركيا لشيخ تميم والشعب القطري لوقوفه بجانب تركيا', 15, 0, NULL, NULL, '2018-08-17 17:07:15', '2018-08-17 17:07:15'),
(206192, 97547, 2, 'دعوة الرئيس التركي مواطني بلاده الي دعم الليرة ردا علي فرض الرسوم الجمركية علي واردات الالومنيوم والصلب التركية', 'دعوة الرئيس التركي مواطني بلاده الي دعم الليرة ردا علي فرض الرسوم الجمركية علي واردات الالومنيوم والصلب التركية', 17, 0, NULL, NULL, '2018-08-17 17:09:26', '2018-08-17 17:09:26'),
(206193, 97547, 2, 'https://arabicpost.net/politics/2018/08/14/الليرة-التركية-تتعافى-حزمة-قرارات-أصد/', 'https://arabicpost.net/politics/2018/08/14/الليرة-التركية-تتعافى-حزمة-قرارات-أصد/', 20, 0, NULL, NULL, '2018-08-17 17:13:42', '2018-08-17 17:13:42'),
(206618, 88336, 2, 'وقعت قطر وتركيا اتفاقية جديدة، في سبيل إسعاف الاقتصاد التركي الذي تأثر سلبا منذ فرض الولايات المتحدة الأمريكية رسوما على واردات الألومنيوم والصلب التر', 'وقعت قطر وتركيا اتفاقية جديدة، في سبيل إسعاف الاقتصاد التركي الذي تأثر سلبا منذ فرض الولايات المتحدة الأمريكية رسوما على واردات الألومنيوم والصلب التركية.\\n\\n', 13, 0, 'image', NULL, '2018-08-18 12:57:11', '2018-08-18 12:57:11'),
(206634, 88336, 2, 'أضاف أردوغان فيما يبدو تحديا لواشنطن &quot;تركيا لم ولن ترضخ لأولئك الذين يتظاهرون بأنهم شركاء استراتيجيون ويحاولون جعلها هدفا&quot;، وفق ما نقلت وكال', 'أضاف أردوغان فيما يبدو تحديا لواشنطن &quot;تركيا لم ولن ترضخ لأولئك الذين يتظاهرون بأنهم شركاء استراتيجيون ويحاولون جعلها هدفا&quot;، وفق ما نقلت وكالة &quot;الأناضول&quot;.', 9, 0, 'image', NULL, '2018-08-18 13:30:46', '2018-08-18 13:30:46'),
(206637, 88336, 2, '&quot;مكدونالدز&quot; و&quot;برغر كينغ&quot; سلاح تركي في معركة الليرة\\nرفضت بلدية العاصمة أنقرة، مؤخرا، منح تراخيص لمقاه ومطاعم تابعة لشركات أميركية ', '&quot;مكدونالدز&quot; و&quot;برغر كينغ&quot; سلاح تركي في معركة الليرة\\nرفضت بلدية العاصمة أنقرة، مؤخرا، منح تراخيص لمقاه ومطاعم تابعة لشركات أميركية وعالمية، وسط أزمة دبلوماسية غير مسبوقة بين تركيا والولايات المتحدة', 8, 0, 'image', NULL, '2018-08-18 13:35:01', '2018-08-18 13:35:01'),
(207047, 88360, 2, 'أبلغ وزير الخارجية وعضو مجلس الدولة الصينى وانج يى نظيره التركى مولود تشاووش أوغلو اليوم السبت، بأن بكين تدعم جهود الحكومة التركية لحماية أمنها واستقر', 'أبلغ وزير الخارجية وعضو مجلس الدولة الصينى وانج يى نظيره التركى مولود تشاووش أوغلو اليوم السبت، بأن بكين تدعم جهود الحكومة التركية لحماية أمنها واستقرار اقتصادها وأنها تؤمن بقدرة أنقرة على تجاوز &quot;الصعوبات العابرة&quot; التى تواجهها.\\n\\n', 8, 0, 'image', NULL, '2018-08-19 16:19:13', '2018-08-19 16:19:13'),
(207048, 88360, 2, 'لبى رجل الأعمال الفلسطيني جهاد شامية، دعوة الرئيس التركي رجب طيب أردوغان، بتحويله نحو 800 ألف دولار إلى العملة التركية، دعما لها في مواجهة الحرب الاقت', 'لبى رجل الأعمال الفلسطيني جهاد شامية، دعوة الرئيس التركي رجب طيب أردوغان، بتحويله نحو 800 ألف دولار إلى العملة التركية، دعما لها في مواجهة الحرب الاقتصادية على تركيا.\\n\\n', 8, 0, NULL, NULL, '2018-08-19 16:25:09', '2018-08-19 16:25:09'),
(207049, 88360, 2, 'أعربت الصين عن دعمها لجهود تركيا في حماية أمنها القومي واستقرارها ونموها الاقتصادي والاجتماعي، في ظل الحرب الاقتصادية التي أعلنتها قوى دولية عليها، بح', 'أعربت الصين عن دعمها لجهود تركيا في حماية أمنها القومي واستقرارها ونموها الاقتصادي والاجتماعي، في ظل الحرب الاقتصادية التي أعلنتها قوى دولية عليها، بحسب ما نقلته وكالة &quot;الأناضول&quot;.\\n\\n', 7, 0, NULL, NULL, '2018-08-19 16:26:05', '2018-08-19 16:26:05'),
(207050, 88360, 2, 'فى مدينة اسطنبول التركيه انضم مطعم الى حمله لدعم العملة الوطنية الليرا التركيه وراح يقدم شطائر السمك المعشوقة لدى الكثيرين بالمجان لكل من يلبون دعوة ا', 'فى مدينة اسطنبول التركيه انضم مطعم الى حمله لدعم العملة الوطنية الليرا التركيه وراح يقدم شطائر السمك المعشوقة لدى الكثيرين بالمجان لكل من يلبون دعوة الرئيس طيب اردوغان تحويل الدولار الى الليرا التركيه \\n', 9, 0, NULL, NULL, '2018-08-19 16:30:48', '2018-08-19 16:30:48'),
(207051, 88360, 2, 'أطلق سياسيون باكستانيون، ونشطاء مجتمع مدني، على مواقع التواصل الاجتماعي، السبت، حملة شعبية مدتها 3 أيام حملت اسم &ldquo;اشتروا الليرة&rdquo; للتضامن م', 'أطلق سياسيون باكستانيون، ونشطاء مجتمع مدني، على مواقع التواصل الاجتماعي، السبت، حملة شعبية مدتها 3 أيام حملت اسم &ldquo;اشتروا الليرة&rdquo; للتضامن مع تركيا.\\n\\n', 12, 0, 'image', NULL, '2018-08-19 16:39:37', '2018-08-19 16:39:37'),
(207053, 88360, 2, 'في رسالة مصورة بمناسبة عيد الأضحى الذي يحتفل به المسلمون الأسبوع الجاري، اعتبر الرئيس التركي، رجب طيب أردوغان، الإثنين، أنه &quot;لا فرق بين من يهاجم ', 'في رسالة مصورة بمناسبة عيد الأضحى الذي يحتفل به المسلمون الأسبوع الجاري، اعتبر الرئيس التركي، رجب طيب أردوغان، الإثنين، أنه &quot;لا فرق بين من يهاجم اقتصادنا، وبين من يهاجم صوت آذاننا وعلمنا، الهدف واحد، وهو هزيمة الشعب التركي وإركاعه ووضعه تحت الوصاية', 10, 0, NULL, NULL, '2018-08-20 13:17:56', '2018-08-20 13:17:56'),
(207054, 88360, 2, 'البنك المركزي القطري يوقع اتفاقية مع نظيره التركي لمبادلة العملات', 'البنك المركزي القطري يوقع اتفاقية مع نظيره التركي لمبادلة العملات', 9, 0, NULL, NULL, '2018-08-20 13:54:57', '2018-08-20 13:54:57'),
(207059, 88360, 2, 'قال الرئيس التركي رجب طيب أردوغان إن الهدف من الهجوم الاقتصادي هو هزم الشعب وتركيع تركيا وفقا لتعبيره.\\n\\n', 'قال الرئيس التركي رجب طيب أردوغان إن الهدف من الهجوم الاقتصادي هو هزم الشعب وتركيع تركيا وفقا لتعبيره.\\n\\n', 11, 0, NULL, NULL, '2018-08-20 14:40:56', '2018-08-20 14:40:56'),
(207061, 88360, 2, 'أعلنت تركيا عزمها على التعاون مع دول أخرى، بما فيها روسيا، في إطار القضية التي رفعتها إلى منظمة التجارة العالمية ضد الولايات المتحدة.\\n\\n', 'أعلنت تركيا عزمها على التعاون مع دول أخرى، بما فيها روسيا، في إطار القضية التي رفعتها إلى منظمة التجارة العالمية ضد الولايات المتحدة.\\n\\n', 8, 0, 'image', NULL, '2018-08-20 22:39:03', '2018-08-20 22:39:03'),
(207062, 88360, 2, 'تقدمت الحكومة التركية إلى منظمة التجارة العالمية بشكوى ضد الرسوم الجمركية الإضافية التي فرضتها الولايات المتحدة على وارداتها من الصلب والألومنيوم.\\n\\n', 'تقدمت الحكومة التركية إلى منظمة التجارة العالمية بشكوى ضد الرسوم الجمركية الإضافية التي فرضتها الولايات المتحدة على وارداتها من الصلب والألومنيوم.\\n\\n', 10, 0, 'image', NULL, '2018-08-20 22:42:03', '2018-08-20 22:42:03'),
(207063, 88786, 2, 'استقرت الليرة التركية مقابل الدولار، اليوم الأربعاء، بعدما قال مستشار الأمن القومي للرئيس الأمريكي، جون بولتون، إن تركيا ارتكبت &quot;خطأ كبيرا&quot; ', 'استقرت الليرة التركية مقابل الدولار، اليوم الأربعاء، بعدما قال مستشار الأمن القومي للرئيس الأمريكي، جون بولتون، إن تركيا ارتكبت &quot;خطأ كبيرا&quot; بعدم إطلاق سراح القس الأمريكي.\\n\\n', 5, 0, 'image', NULL, '2018-08-22 16:08:10', '2018-08-22 16:08:10'),
(207126, 88788, 2, 'أردوغان متحديا: تركيا لم ولن ترضخ\\nهل سيظل صامد امام ما يحدث ؟', 'أردوغان متحديا: تركيا لم ولن ترضخ\\nهل سيظل صامد امام ما يحدث ؟', 3, 0, NULL, NULL, '2018-08-23 17:40:53', '2018-08-23 17:40:53'),
(207127, 88788, 2, 'ميركل: لا أحد لديه مصلحة في زعزعة استقرار الاقتصاد التركي\\n', 'ميركل: لا أحد لديه مصلحة في زعزعة استقرار الاقتصاد التركي\\n', 4, 0, NULL, NULL, '2018-08-23 17:41:10', '2018-08-23 17:41:10'),
(207128, 88788, 2, 'أردوغان: نقول &quot;مع السلامة&quot; لمن يفرط بشراكته الاستراتيجية مع تركيا\\n', 'أردوغان: نقول &quot;مع السلامة&quot; لمن يفرط بشراكته الاستراتيجية مع تركيا\\n', 5, 0, NULL, NULL, '2018-08-23 17:42:25', '2018-08-23 17:42:25'),
(207129, 88788, 2, 'أردوغان: سنتعامل بالعملات المحلية مع أوروبا إذا خرجت من &quot;قبضة الدولار&quot;\\n', 'أردوغان: سنتعامل بالعملات المحلية مع أوروبا إذا خرجت من &quot;قبضة الدولار&quot;\\n', 4, 0, NULL, NULL, '2018-08-23 17:43:41', '2018-08-23 17:43:41'),
(207284, 88791, 2, 'أكد ضاحى خلفان تميم، رئيس شرطة دبى السابق، أن قطر تلعب سيناريو إرهابى، حيث تدفع المليارات لدعم تركيا فى احتجاز القس الأمريكى، وتلعب دور الوسيط للإفراج', 'أكد ضاحى خلفان تميم، رئيس شرطة دبى السابق، أن قطر تلعب سيناريو إرهابى، حيث تدفع المليارات لدعم تركيا فى احتجاز القس الأمريكى، وتلعب دور الوسيط للإفراج عنه فى نفس الوقت.\\nهل بالفعل قطر تلعب دور الارهاب وليها اغراض اخرى ؟', 3, 0, NULL, NULL, '2018-08-25 14:37:30', '2018-08-25 14:37:30'),
(207285, 88791, 2, 'تراجعت الليرة اليوم الخميس لتظل تحت ضغط مع استمرار المواجهة الموجعة بين تركيا والولايات المتحدة بخصوص مصير رجل دين مسيحى دون بادرة حل.\\nهل تسليم القس ', 'تراجعت الليرة اليوم الخميس لتظل تحت ضغط مع استمرار المواجهة الموجعة بين تركيا والولايات المتحدة بخصوص مصير رجل دين مسيحى دون بادرة حل.\\nهل تسليم القس هيوقف الازمة بين البلدين؟؟؟؟', 4, 0, NULL, NULL, '2018-08-25 14:40:49', '2018-08-25 14:40:49'),
(207286, 88791, 2, 'هل الانقلاب الفاشل على تركيا هو السبب فيما يحدث وتتدمير الليرة التركيه وايقاع الاقتصاد ؟؟', 'هل الانقلاب الفاشل على تركيا هو السبب فيما يحدث وتتدمير الليرة التركيه وايقاع الاقتصاد ؟؟', 2, 0, NULL, NULL, '2018-08-25 14:43:12', '2018-08-25 14:43:12'),
(207287, 88791, 2, 'ماذا لدى امريكا ايضا لتفعلة هل المصالحة ام ستستمر فى رفض المفاوضات ؟', 'ماذا لدى امريكا ايضا لتفعلة هل المصالحة ام ستستمر فى رفض المفاوضات ؟', 4, 0, NULL, NULL, '2018-08-25 14:44:26', '2018-08-25 14:44:26'),
(207289, 88791, 2, 'بعد دعم قطر وروسيا وبعض الدول ببعض المساعدات المعاملة بالليرا هل يوجد حلول اخرى؟', 'بعد دعم قطر وروسيا وبعض الدول ببعض المساعدات المعاملة بالليرا هل يوجد حلول اخرى؟', 3, 0, NULL, NULL, '2018-08-25 14:47:31', '2018-08-25 14:47:31'),
(207290, 88791, 2, 'أعلنت وزيرة التجارة التركية روهصار بكجان اليوم الجمعة أن #تركيا ستردّ في حال قررت الولايات المتحدة فرض عقوبات جديدة', 'أعلنت وزيرة التجارة التركية روهصار بكجان اليوم الجمعة أن #تركيا ستردّ في حال قررت الولايات المتحدة فرض عقوبات جديدة', 4, 0, NULL, NULL, '2018-08-25 14:48:20', '2018-08-25 14:48:20'),
(207291, 88791, 2, 'تصريحات المستشار الامن القومى الامريكى عن اقتصاد تركيا وهبوط الليرا معناة استهداف تركيا اقتصاديا ؟', 'تصريحات المستشار الامن القومى الامريكى عن اقتصاد تركيا وهبوط الليرا معناة استهداف تركيا اقتصاديا ؟', 4, 0, NULL, NULL, '2018-08-25 15:26:49', '2018-08-25 15:26:49'),
(207292, 88791, 2, 'على خلفية الأزمة في العلاقات مع الولايات المتحدة وهبوط الليرة، تمكن الرئيس التركي أردوغان من الحفاظ على دعم السكان. نجح في حشد المعارضة والسكان بشعارا', 'على خلفية الأزمة في العلاقات مع الولايات المتحدة وهبوط الليرة، تمكن الرئيس التركي أردوغان من الحفاظ على دعم السكان. نجح في حشد المعارضة والسكان بشعارات معادية لأمريكا ووعد بمشاريع ضخمة. عداء امريكا والحرب بهذا الشكل هتصمد تركيا؟', 5, 0, NULL, NULL, '2018-08-25 15:31:05', '2018-08-25 15:31:05'),
(207293, 88791, 2, 'هل استخدام الإدارة الأمريكية لأدوات مثل التجارة والضرائب والعقوبات على تركيا وبلاد اخرى يظهر أنها عازمة على البدء بحرب تجارية عالمية؟', 'هل استخدام الإدارة الأمريكية لأدوات مثل التجارة والضرائب والعقوبات على تركيا وبلاد اخرى يظهر أنها عازمة على البدء بحرب تجارية عالمية؟', 4, 0, NULL, NULL, '2018-08-25 15:32:40', '2018-08-25 15:32:40'),
(207294, 88791, 2, 'هل من الممكن بجعل كل السلع والمحلات وتعامل تركيا مع باقى الدول بالليرا بان يكون هذا طوق نجاة لاقتصاد تركيا؟', 'هل من الممكن بجعل كل السلع والمحلات وتعامل تركيا مع باقى الدول بالليرا بان يكون هذا طوق نجاة لاقتصاد تركيا؟', 4, 0, NULL, NULL, '2018-08-25 15:50:28', '2018-08-25 15:50:28'),
(207315, 88842, 2, 'اعتبر الرئيس التركي رجب طيب أردوغان أن الصراعات الإقليمية وأزمة العملة الحالية في تركيا، التي وصفها بأنها &quot;حرب اقتصادية&quot;، مرتبطة بمحاولات سا', 'اعتبر الرئيس التركي رجب طيب أردوغان أن الصراعات الإقليمية وأزمة العملة الحالية في تركيا، التي وصفها بأنها &quot;حرب اقتصادية&quot;، مرتبطة بمحاولات سابقة لغزو الأناضول، محذرا من أن مثل هذه الأعمال ستؤدي إلى انهيار المناطق المجاورة.', 0, 0, NULL, NULL, '2018-08-27 13:35:00', '2018-08-27 13:35:00'),
(207316, 88842, 2, 'قال الرئيس التركي، الأحد، مخاطبا حشدا جنوبي شرق البلاد بهذه المناسبة: &quot;أولئك الذين يسعون لمعرفة الأسباب المؤقتة وراء المشكلات التي نواجهها، مخطئو', 'قال الرئيس التركي، الأحد، مخاطبا حشدا جنوبي شرق البلاد بهذه المناسبة: &quot;أولئك الذين يسعون لمعرفة الأسباب المؤقتة وراء المشكلات التي نواجهها، مخطئون جدا. الهجمات التي نواجهها اليوم تضرب بجذورها في التاريخ&quot; هل دى الحقيقة؟', 0, 0, NULL, NULL, '2018-08-27 13:36:34', '2018-08-27 13:36:34'),
(207318, 88842, 2, 'أسهم الانخفاض الحاد في قيمة الليرة التركية، نتيجة الاضطرابات الاقتصادية والتوترات مع الولايات المتحدة، في فائدة واحدة للاقتصاد التركي تمثلت في عودة مج', 'أسهم الانخفاض الحاد في قيمة الليرة التركية، نتيجة الاضطرابات الاقتصادية والتوترات مع الولايات المتحدة، في فائدة واحدة للاقتصاد التركي تمثلت في عودة مجموعات كبيرة من السياح إلى البلاد هذا الصيف', 0, 0, NULL, NULL, '2018-08-27 13:36:59', '2018-08-27 13:36:59'),
(207319, 88842, 2, 'أردوغان: إذا انهارت تركيا لن يكون هناك شرق أوسط أو إفريقيا\\n هل سقوط تركيا هيؤدى الى اسقاط دول اخرى ؟\\n', 'أردوغان: إذا انهارت تركيا لن يكون هناك شرق أوسط أو إفريقيا\\n هل سقوط تركيا هيؤدى الى اسقاط دول اخرى ؟\\n', 0, 0, NULL, NULL, '2018-08-27 13:38:24', '2018-08-27 13:38:24'),
(207320, 88842, 2, 'في تطور جديد لمسلسل هبوط الليرة منيت العملة التركية بضربة قوية جديدة، الاثنين، بعدما تراجعت بنسبة 3 بالمئة أمام الدولار\\nهل سيستمر الوضع هكذا بدون حلو', 'في تطور جديد لمسلسل هبوط الليرة منيت العملة التركية بضربة قوية جديدة، الاثنين، بعدما تراجعت بنسبة 3 بالمئة أمام الدولار\\nهل سيستمر الوضع هكذا بدون حلول ؟', 0, 0, NULL, NULL, '2018-08-27 13:42:50', '2018-08-27 13:42:50'),
(207321, 88842, 2, 'قدم متحدث باسم الرئيس التركي رجب طيب أردوغان، الأربعاء، ما وصفه بالدليل على أن الإدارة الأميركية تستهدف شريكا لها في حلف شمال الأطلسي، في إطار حرب اقت', 'قدم متحدث باسم الرئيس التركي رجب طيب أردوغان، الأربعاء، ما وصفه بالدليل على أن الإدارة الأميركية تستهدف شريكا لها في حلف شمال الأطلسي، في إطار حرب اقتصادية. معنى ذلك ان القس والانقلاب فى شبهة لتدمير تركيا مثل البلاد الاخرى ؟\\n', 1, 0, NULL, NULL, '2018-08-27 13:43:55', '2018-08-27 13:43:55'),
(207503, 87280, 2, 'قال أردوغان، في حفل لتوزيع جوائز الإعلام بأنقرة، اليوم الأربعاء: &quot;بالطبع هناك مشاكل بنيوية في الاقتصاد التركي نعمل على حلها لكن هناك جهات تعمل عل', 'قال أردوغان، في حفل لتوزيع جوائز الإعلام بأنقرة، اليوم الأربعاء: &quot;بالطبع هناك مشاكل بنيوية في الاقتصاد التركي نعمل على حلها لكن هناك جهات تعمل على محاصرتنا من خلال الاقتصاد&quot;.', 0, 0, NULL, NULL, '2018-08-29 18:49:12', '2018-08-29 18:49:12'),
(207510, 87280, 2, 'هل ستقدم ألمانيا مساعدة لتركيا وسط أزمة الليرة؟\\n', 'هل ستقدم ألمانيا مساعدة لتركيا وسط أزمة الليرة؟\\n', 1, 0, NULL, NULL, '2018-08-29 19:31:22', '2018-08-29 19:31:22'),
(207565, 87280, 2, 'أصدرت الرئاسة التركية صباح اليوم الجمعة، قرارا يقضي بخفض الضريبة على الودائع بالليرة التركية، وزيادتها على الودائع بالعملات الأجنبية، بهدف زيادة الإقب', 'أصدرت الرئاسة التركية صباح اليوم الجمعة، قرارا يقضي بخفض الضريبة على الودائع بالليرة التركية، وزيادتها على الودائع بالعملات الأجنبية، بهدف زيادة الإقبال على العملة التركية.\\n\\n', 0, 0, NULL, NULL, '2018-08-31 19:51:24', '2018-08-31 19:51:24'),
