(233099, 181, 216, 'موضوع في المجموعة', NULL, 0, 0, NULL, NULL, '2022-02-10 15:38:14', '2022-02-10 15:38:14'),
(233125, 181, 215, 'ثقافة العيب هي ظاهرة من الظواهر التي يرفض فيها مجتمعٌ ما قبولَ شيءٍ لا يتناسب مع العادات، والتقاليد السائدة، أو النظرة الفكرية المشتركة بين الأفراد عم', 'ثقافة العيب هي ظاهرة من الظواهر التي يرفض فيها مجتمعٌ ما قبولَ شيءٍ لا يتناسب مع العادات، والتقاليد السائدة، أو النظرة الفكرية المشتركة بين الأفراد عموماً، وترتبط ثقافة العيب عادةً بظهورِ شيءٍ جديدٍ وغير مألوف أو معروف مسبقاً وقد يكون معتمداً على ثقافة غيرية؛ بمعنى مأخوذ من المجتمعات الأخرى، لذلك يعتبر مرفوضاً، وغير مقبول؛ بسبب عدم توافقهِ مع الأفكار الثقافية، والاجتماعية، وحتى الأخلاقية داخل المجتمع الواحد.\\nما هي أسباب ظهور ثقافة العيب؟ وما هي أنواعها ؟\\n', 0, 0, NULL, NULL, '2022-02-13 14:12:39', '2022-02-13 14:12:39'),
(233126, 181, 215, 'على الرغم من وجود النظام الإسلامي العادل، فإنَّ عراقيل كثيرة في تاريخنا الطويل قد حالت في معظم فتراته - لا سيما بعد سقوط الخلافة الراشدة - دون تحقيق أ', 'على الرغم من وجود النظام الإسلامي العادل، فإنَّ عراقيل كثيرة في تاريخنا الطويل قد حالت في معظم فتراته - لا سيما بعد سقوط الخلافة الراشدة - دون تحقيق أهدافه ومبادئه على الوجه الصحيح، وكانت النتيجة الحتميَّة عدم بلورة التطبيقات السليمة له، بحيث تؤدي إلى تأصيل جذوره وتثبيت دعائمه لتشكل أطرًا ثابتة وواضحة، يصعب التلاعب بها أو طمس معالمها النظرية والتطبيقية في الصدر الأول، وإنكار أهدافها العادلة التي جاءت بها لبناء الحياة الآمنة، علمًا أن تأثير العدل الإسلامي واضحٌ جدًّا، حتى في عصور الانحراف بحيث لو قيس تاريخنا الاقتصادي بالتواريخ الاقتصادية للأمم الأخرى، كان تاريخنا عادلاً بالنسبة إلى التواريخ الأخرى. يقول الاقتصادي الفرنسي: &quot;جاك أوستري&quot;: (إن طريق الإنماء الاقتصادي ليس مَحصورًا في المذهبين المعروفين الرأسمالي والاشتراكي، بل هنالك مذهب اقتصادي ثالث راجح هو المذهب الاقتصادي الإسلامي)، ويقول: (إنَّ هذا المذهب سيسود عالم المستقبل؛ لأنه أسلوب كامل للحياة.\\nما هي مقومات النظام الاقتصادي الإسلامي؟ وما هو دوره في التنمية؟', 0, 0, NULL, NULL, '2022-02-13 14:13:41', '2022-02-13 14:13:41'),
(233127, 181, 5, 'موضوع في المجموعة', NULL, 0, 0, NULL, NULL, '2022-02-13 14:15:26', '2022-02-13 14:15:26'),
(233150, 181, 215, 'هناك أمور تعين المسلم السالك طريق الله على إخلاص النية والعمل لله تعالى ، وتدفعه إلى الأمام في طريق المخلصين، وتساعده على تحرير نفسه، وتنقية دواعيه من', 'هناك أمور تعين المسلم السالك طريق الله على إخلاص النية والعمل لله تعالى ، وتدفعه إلى الأمام في طريق المخلصين، وتساعده على تحرير نفسه، وتنقية دواعيه من الشوائب الذاتية والدنيوية ومنها العلم الراسخ\\n\\nوهو أن يعلم ما هو الإخلاص وأهمية ، وثمراته في الدنيا والآخرة، وأن الله تعالى\\n لا يقبل عملا إلا بإخلاص، مهما تكن صورته، وأنه تعالى مطلع على ما في قلبه، فهو يعلم السر وأخفى، ولا تخفى عليه خافية، كما قال إبراهيم عليه السلام: (ربنا إنك تعلم ما نخفي وما نعلن، وما يخفى على الله من شيء في الأرض ولا في السماء).', 0, 0, NULL, NULL, '2022-02-14 19:51:40', '2022-02-14 19:51:40'),
(233151, 181, 215, '\\nالشباب في مرحلة المراهقة مهيئون أكثر من غيرهم لتقليد الشخصيات؛ نعم.. فهم محتاجون لقدوة ومعلم يرشدهم إلى الطريق.. إذا لم تقف الأسرة مع أبنائها في هذه', '\\nالشباب في مرحلة المراهقة مهيئون أكثر من غيرهم لتقليد الشخصيات؛ نعم.. فهم محتاجون لقدوة ومعلم يرشدهم إلى الطريق.. إذا لم تقف الأسرة مع أبنائها في هذه المرحلة التأسيسية... فإلى من يلجأ الشباب إذن ليكون قدوته ؟\\nإن الأمة تحتاج منا شباباً عالمين عاملين، وإلا فنحن في أمية من نوع آخر ليست هي الجهل بالقراءة، بل هي الجهل بالتزام ما نعتقده ونعلمه ونقرؤه التزاماً عملياً في كل شؤون حياتنا؛ في المنزل، والمكتب، والشارع، والمصنع.\\nالعمر الذي يملكه الإنسان نعمة كبرى يحمد الله عليها، والحياة أمامه فرصة للنجاح، ولذلك امتن الله بالليل والنهار على عباده، فقال تعالى: {اللَّهُ الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِراً إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ النَّاسِ لا يَشْكُرُونَ} [غافر: 61].\\n من وجهة نظركم ما مدى أهمية دور الشباب في بناء الأمة ونهضتها؟\\nوما النتيجة المتوقعة إذا قمنا بعمل مقارنة بين اهتمامات شباب الماضي وشباب الحاضر في ظل التكنولوجيا والانترنت؟\\n', 0, 0, NULL, NULL, '2022-02-14 20:02:03', '2022-02-14 20:02:03'),
(233413, 181, 215, '▪️{مَن جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا ۖ وَمَن جَاءَ بِالسَّيِّئَةِ فَلَا يُجْزَىٰ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ الأنعام} 160', '▪️{مَن جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا ۖ وَمَن جَاءَ بِالسَّيِّئَةِ فَلَا يُجْزَىٰ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ الأنعام} 160\\n\\n▪️{مَن جَاءَ بِالْحَسَنَةِ فَلَهُ خَيْرٌ مِّنْهَا وَهُم مِّن فَزَعٍ يَوْمَئِذٍ آمِنُونَ} النمل 89\\n\\n\\n▪️{مَن جَاءَ بِالْحَسَنَةِ فَلَهُ خَيْرٌ مِّنْهَا ۖ وَمَن جَاءَ بِالسَّيِّئَةِ فَلَا يُجْزَى الَّذِينَ عَمِلُوا السَّيِّئَاتِ إِلَّا مَا كَانُوا يَعْمَلُونَ }القصص 84\\n\\n&bull;حدد جزاء الحسنه بعشر أمثالها والسيئه بمثلها في السورة الأطول\\n&bull;وفي سورة النمل حدد الحسنة في آيه \\n&bull;وفي سورة القصص اختصرت الحسنة والسيئة في نفس الآيه', 0, 0, NULL, NULL, '2022-02-23 18:02:39', '2022-02-23 18:02:39'),
(233414, 181, 215, 'ترتبط العديد من المشكلات الاجتماعية في المجتمع بضعف القيادة  ، ولكن جميع المشكلات الاجتماعية مرتبطة بقيادة الدول والشركات والمجموعات الأخرى.\\n &rlm;عن', 'ترتبط العديد من المشكلات الاجتماعية في المجتمع بضعف القيادة  ، ولكن جميع المشكلات الاجتماعية مرتبطة بقيادة الدول والشركات والمجموعات الأخرى.\\n &rlm;عندما يفتقر القادة إلى القدرة على توفير التوجيه والتدريب والتحفيز للموظفين ، غالبًا ما تتأثر الثقافة التنظيمية والروح المعنوية.\\n &rlm;والقيادة السيئة هي السبب الجذري لارتفاع معدل دوران الموظفين وفقدان الإنتاجية.\\n\\n\\nكيف تؤثر القيادة الضعيفة على ثقافتك؟\\nوكيف يتمكن القادة من  دعم موظفيهم وتفويضهم وإلهامهم والاحتفاء بهم وتحديهم لتحقيق الأداء على أعلى مستوى؟', 0, 0, NULL, NULL, '2022-02-23 18:03:12', '2022-02-23 18:03:12'),
(233468, 181, 215, 'تنقسم المجتمعات البشرية الى ثلاث فئات وهي المجتمع الزراعي، والمجتمع الصناعي، ومجتمعات ما بعد الصناعية أي مجتمعات المعرفة المعلوماتية، ويعد التغيير الث', 'تنقسم المجتمعات البشرية الى ثلاث فئات وهي المجتمع الزراعي، والمجتمع الصناعي، ومجتمعات ما بعد الصناعية أي مجتمعات المعرفة المعلوماتية، ويعد التغيير الثالث الأكثر أهمية في حياة البشرية حيث سمي بـ (الثورة المعلوماتية).\\nوالمقصود بالأمية المعلوماتية، هو افتقار الفرد الى المهارات الأساسية في كيفية استخدام المعلومات بفاعلية، ومن هذه المعلومات هي قدرة الفرد على تحديد حاجته من المعلومات، وقدرته على التعبير عن هذه الحاجة، وبهذا سيتمكن من استخدام المعلومات ويستثمرها الى أقصى درجة سواء في العمل او اموره الحياتية واليومية العامة ومثال على ذلك: كيف يستطيع ان يعثر على عمل، وكيف يخطط لأسرته ويحل مشاكله العائلية وكيف ينتخب ولمن؟.\\nكيف يتم محو الامية المعلوماتية وزيادة الوعي المعلوماتي ؟ وكيف يتم التكيف المستمر مع الابتكارات الناشئة باستمرار في تكنولوجيا المعلومات وفهمها وتقييمها والاستفادة منها؟', 0, 0, NULL, NULL, '2022-02-26 19:28:12', '2022-02-26 19:28:12'),
(233477, 181, 215, 'مِن صفات المُرَبِّي أن يألف ويؤلف، يألف الصغار ويحبهم، ولا يأنف الجلوس معهم، يتبسط في حديثه ويتواضع، يمزح ويلعب، يلين ولا يشتد، يعطي كثيرًا بلا مقابل،', 'مِن صفات المُرَبِّي أن يألف ويؤلف، يألف الصغار ويحبهم، ولا يأنف الجلوس معهم، يتبسط في حديثه ويتواضع، يمزح ويلعب، يلين ولا يشتد، يعطي كثيرًا بلا مقابل، ولا تفارقه الابتسامة، وكذلك يُؤْلَف عند الصغار، وإلا فلا يتصدَّى للتعليم ولا التربية، فهي مهمة ليس هو أهلاً لها، إذ إنه دائمُ التجهُّم، شديد، عنيف، لا تعرف الرحمة طريقًا إلى قلبه، فويل لأبنائه منه تمامًا؛ كمن قال لرسول الله - صلى الله عليه وسلم -: &quot;إنَّ لي عَشْرَةً منَ الولد ما قَبَّلْتُ منهم أحدًا&quot;، فقال له الحبيب المُرَبّي - صلى الله عليه وسلم -: ((مَن لا يَرحم لا يُرْحَم))، وعمر بن الخطاب عَزَل مثل ذلك الرجل عن ولاية المسلمين، فمن لا يألفه أبناؤه، لا يألفه المسلمون، وهو بالتالي لن يرحمهم.', 0, 0, NULL, NULL, '2022-02-27 17:16:33', '2022-02-27 17:16:33'),
(233478, 181, 215, 'تعتبر المشاركة المجتمعية (Community Participation) ركيزة أساسية من ركائز تحقيق الأهداف التنموية للمجتمعات، وتقاس مؤشرات نجاح الخطط التنموية على مدى إش', 'تعتبر المشاركة المجتمعية (Community Participation) ركيزة أساسية من ركائز تحقيق الأهداف التنموية للمجتمعات، وتقاس مؤشرات نجاح الخطط التنموية على مدى إشراك المجتمع المحلي في اتخاذ القرار، لأن جميع الخطط والمشاريع التنموية تستهدف أفراد المجتمع بكل شرائحه.\\nتعد المشاركة المجتمعية إحدى الأدوات التي يمكن من خلالها النهوض بالمجتمع والارتقاء به، والعمل على تحسين مستوى حياة المواطنين اجتماعية واقتصادية وبيئية وحضرية وذلك من خلال إسهام أبناء المجتمع تطوعا في جهود التنمية سواء بالرأي أو بالعمل أو بالتمويل ، وحث الآخرين على المشاركة، وعدم وضع العراقيل أمام الجهود المبذولة من جانب قيادات المجتمع وغير ذلك من الأمور التي تؤدي إلى تنمية المجتمع وتحقيق أهدافه .\\nماهي أساليب المشاركة المجتمعية وصورها ؟ وماهي أنواعها ومستوياتها ؟\\n', 0, 0, NULL, NULL, '2022-02-27 17:16:49', '2022-02-27 17:16:49'),
(233550, 181, 215, 'الفرد كائن إجتماعي يكتسب خصائصه وقيمه الإجتماعية بتفاعله مع الجماعات، هذه الحقيقة تجعلنا ندرك خطورة وأهمية الجماعات التي ينتمي إليها الفرد منذ الولادة', 'الفرد كائن إجتماعي يكتسب خصائصه وقيمه الإجتماعية بتفاعله مع الجماعات، هذه الحقيقة تجعلنا ندرك خطورة وأهمية الجماعات التي ينتمي إليها الفرد منذ الولادة بدءاً بالأسرة ثم رفاق اللعب وجماعات المدرسة وزملاء العمل وجماعات الأصدقاء والروابط والمنظمات وغيرها من الجماعات التي ينمو ويتفاعل فيها الفرد، هذه الجماعات هي المسؤولة عما يميز الفرد من خصال طيبة وغير طيبة، فالجماعة هي البيئة الإجتماعية ومعمل التفاعلات التي تلازم الفرد طوال حياته ويستمد منها مقومات شخصيته الإجتماعية.\\nكيف يستخدم الفرد قدراته ومهاراته المكتسبة كي تنعكس على الأوضاع الإجتماعية التي يعيش فيها؟', 0, 0, NULL, NULL, '2022-03-01 05:24:19', '2022-03-01 05:24:19'),
(233551, 181, 215, 'الذكاء الاصطناعي هو أحد علوم الحاسب الآلي الحديثة التي تبحث عن أساليب متطورة لبرمجته للقيام بأعمال واستنتاجات تشابه ولو في حدود ضيقة تلك الأساليب التي', 'الذكاء الاصطناعي هو أحد علوم الحاسب الآلي الحديثة التي تبحث عن أساليب متطورة لبرمجته للقيام بأعمال واستنتاجات تشابه ولو في حدود ضيقة تلك الأساليب التي تنسب الذكاء الإنسان .\\nفهو بذلك علم يبحث أولا في تعريف الذكاء الإنساني وتحديد أبعاده ، ومن ثم محاكاة بعض خواصه ، وهنا يجب توضيح أن هذا العلم لا يهدف إلى مقارنة أو تمثيل العقل البشري الذي خلقه الله جلت قدرته وعظمته بالآلة التي هي من صنع المخلوق ، بل يهدف هذا العلم الجديد إلى فهم العمليات الذهنية المعقدة التي يقوم بها العقل البشري أثناء ممارسته (التفكير) ومن ثم ترجمة هذه العمليات الذهنية إلى ما يوازيها من عمليات محاسبية تزيد من قدرة الحاسب على حل المشاكل المعقدة وهو الذكاء الاصطناعي .\\nما هي وظائفه ، تطبيقاته ، خصائصه ، اهدافه ، انواعه وأهميته ؟\\n', 0, 0, NULL, NULL, '2022-03-01 05:25:25', '2022-03-01 05:25:25'),
(233664, 181, 215, 'لقد حضَّ الرسول - عليه الصلاة والسلام - على مبدأ الإخاء وإعلانه وتطبيقه منذ قَدِم المدينة؛ كما جاء في سيرة ابن هشام؛ حيث روى أن الرسول - عليه الصلاة و', 'لقد حضَّ الرسول - عليه الصلاة والسلام - على مبدأ الإخاء وإعلانه وتطبيقه منذ قَدِم المدينة؛ كما جاء في سيرة ابن هشام؛ حيث روى أن الرسول - عليه الصلاة والسلام - حينما قَدِم المدينة كتب كتابًا بين المؤمنين والمهاجرين مع أهل يثرب من المدينة، ومَن جاورهم من اليهود، جاء فيه: ((هذا كتاب من محمد النبي رسول الله - صلى الله عليه وسلم - بين المؤمنين والمسلمين من قريش وأهل يثرب، ومَن معهم، فلَحِق بهم، فحلَّ معهم، وجاهَد معهم، إنهم أمة واحدة من دون الناس)).\\nوهذا أول دستور عرَفته البشرية يُحدِّد إقليم الدولة الإسلامية، وهو المدينة، ويحدد شعبها وهم المسلمون، والأقليات التي تعيش معهم، ويحدِّد دستورها، وهو كتاب الله وسُنة رسولنا محمد- عليه الصلاة والسلام -  .\\n', 0, 0, NULL, NULL, '2022-03-02 11:22:16', '2022-03-02 11:22:16'),
(233757, 181, 215, 'التفكير الناقد من أكثر أشكال التفكير المركب استحواذا على اهتمام الباحثين، و المفكرين التربويين الذين عرفوا بكتاباتهم في مجال التفكير، كما أن تعبير &qu', 'التفكير الناقد من أكثر أشكال التفكير المركب استحواذا على اهتمام الباحثين، و المفكرين التربويين الذين عرفوا بكتاباتهم في مجال التفكير، كما أن تعبير &quot; التفكير الناقد &quot; من أكثر التعبيرات التي قد يساء استعمالها من قبل الكثيرين في وصف عمليات التفكير ومهاراته ، وفي عالم الواقع يستخدم التعبير للدلالة على معان عديدة أهمها: الكشف عن العيوب و الأخطاء ، الشك في كل شيء، التفكير التحليلي، التفكير التأملي ، حل المشكلة ، كل مهارات التفكير العليا المستقل ، والتعرف على أوجه التحيز والتناقض وعدم الاتساق. التفكير الناقد من أهم أنماط التفكير التي تساعد الفرد على نقد المعلومات الناتجة عن الانفجار المعرفي، والتقدم العلمي الهائل، ومن ثمة التوصل إلى المعلومات الصحيحة، وتوظيفها لتحقيق أهدافه وأهداف المجتمع .تنمية التفكير الناقد ضرورة تربوية لإعداد الأفراد الذين لديهم القدرة على نقد الأفكار الناتجة، والحلول المقترحة للمشكلات، وإخضاع هذه الأفكار والحلول للمنطق؛ لذلك كان أساس التفكير الناقد أساسا فلسفية .\\nماهي أهمية التفكير الناقد وما هي أبعاده ؟وماهو دور المناهج  التعليمية في تنمية التفكير الناقد ؟\\n', 0, 0, NULL, NULL, '2022-03-05 04:58:18', '2022-03-05 04:58:18'),
(233758, 181, 215, 'اللغة العربية هي من صميم الهوية وجزء أصيل من حصاد الحضارة ـ لا يخفى واقعها على أي مهتم بقضيتها، وكل شعب من الشعوب يريد أن ينهض ويتقدم فلابد من اهتمامه', 'اللغة العربية هي من صميم الهوية وجزء أصيل من حصاد الحضارة ـ لا يخفى واقعها على أي مهتم بقضيتها، وكل شعب من الشعوب يريد أن ينهض ويتقدم فلابد من اهتمامه بلغته،  وإذا نظرنا إلى المشروعات الفكرية والإصلاحية الإسلامية ـ المعاصرة منها على الأقل ـ لوجدنا الاهتمام باللغة العربية ضمن محاور هذا المشروع.\\nكيف نحافظ على اللغة العربية وكيف يكون تعزيز الهوية والانتماء؟\\n', 0, 0, NULL, NULL, '2022-03-05 04:59:37', '2022-03-05 04:59:37'),
(233800, 181, 215, 'من طبيعة البشر وفطرتهم أن يتأثروا بالمحاكاة والقدوة أكثر من القراءة والسمع، والطفل في مرحلة الطفولة المبكرة تكون لديه مجموعة من السمات توهله لاستقبال ', 'من طبيعة البشر وفطرتهم أن يتأثروا بالمحاكاة والقدوة أكثر من القراءة والسمع، والطفل في مرحلة الطفولة المبكرة تكون لديه مجموعة من السمات توهله لاستقبال كل سلوك إيجابي والعمل به. \\nكيف نربي أبناءنا بعيدًا عن تقليد الأخرين؟', 0, 0, NULL, NULL, '2022-03-07 06:13:06', '2022-03-07 06:13:06'),
(233809, 181, 215, 'من يراقب سلوكيات بعض أولادنا الاقتصادية يجد أن بعضها بل معظمها منهي عنه شرعًا، وللأسف لا نهتم بها، أو لا نعبأ بذلك، بل نجد بعض الآباء يزكوا تلك السلبي', 'من يراقب سلوكيات بعض أولادنا الاقتصادية يجد أن بعضها بل معظمها منهي عنه شرعًا، وللأسف لا نهتم بها، أو لا نعبأ بذلك، بل نجد بعض الآباء يزكوا تلك السلبيات من باب العاطفة والتدليل.. وتكون من أخطر أبواب المفاسد عقديًّا وأخلاقيًّا وسلوكيًّا على الأولاد في الحاضر والمستقبل.\\n\\n\\nلذلك فإنه من الأهمية أن نربي أولادنا على ضرورة تجنب هذه السلوكيات السيئة ويكون من داخلهم الباعث والحافز والدافع على تجنبها عبادة لله وطاعة، وحبًّا وامتثالاً لرسوله صلى الله عليه وسلم وكذلك حبًّا للوالدين.\\nكيف نعلم أولادنا الآداب السلوكية الاقتصادية الإسلامية ؟\\n', 0, 0, NULL, NULL, '2022-03-07 06:18:14', '2022-03-07 06:18:14'),
(233837, 181, 215, 'تتعدد طرق وأساليب انتقام الزوجين بعد الطلاق، عندما تقع الأم تحت ضغوط الحياة بعد تخلي الأب عن واجباته، هنا تبدأ الزوجة باتباع أساليب الكيد والانتقام، و', 'تتعدد طرق وأساليب انتقام الزوجين بعد الطلاق، عندما تقع الأم تحت ضغوط الحياة بعد تخلي الأب عن واجباته، هنا تبدأ الزوجة باتباع أساليب الكيد والانتقام، وفي بعض الحالات قيام الأم بحرمان الأب من رؤية أولاده .\\nوينتقم الأب أيضاً باستمراره في امتناعه عن الإنفاق على أولاده حتى تستمر معاناة الأم متلذذاً بالشماتة والتشفي ومتجاهلاً في الوقت نفسه معاناة أولاده وغير عابئ بآثار ذلك، مثل التهديد بالطرد من المدرسة بسبب عدم سداد الرسوم الدراسية أو حرمانهم من شهاداتهم، أو تبدو عليهم علامات الفقر مقارنة بأقرانهم.\\nالكثير من الأباء يتهربون من النفقة بداعي الانتقام، بالمقابل نجد بعض الأمهات يكدن لمطلقيهنَّ عبر التهرب من مسؤوليتهن تجاه تربية أطفالهن، بقصد الانتقام من مطلقيهن، وفي النهاية الأبناء هم من يدفع ثمن الطلاق.\\nكيف  نجنب الأبناء الأثر النفسي والاجتماعي لما يسمى انتقام الزوجين بعد الطلاق؟\\n', 0, 0, NULL, NULL, '2022-03-08 05:21:52', '2022-03-08 05:21:52'),
(233839, 181, 215, 'البناء الاجتماعي هو الإطار التنظيمي العام الذي يندرج تحته كافة أوجه السلوك الإنساني في مجتمع ما ويتضمن مجموعة النظم الاجتماعية ذات القواعد السلوكية ال', 'البناء الاجتماعي هو الإطار التنظيمي العام الذي يندرج تحته كافة أوجه السلوك الإنساني في مجتمع ما ويتضمن مجموعة النظم الاجتماعية ذات القواعد السلوكية المستقرة التي تحكم الأنشطة الإنسانية المتعددة في مجتمع ما.. وبمعنى آخر يمكن تعريف البناء الاجتماعي بأنه مجموعة الأطر التنظيمية التي تنتظم في إطارها كافة العلاقات الإنسانية، سواء تلك العلاقات البينية بين الأفراد أو الأشخاص داخل مجتمع ما، أو تلك العلاقات التبادلية بين الأفراد في مجتمع ما وغيره من المجتمعات.\\nمما يتكون البناء الاجتماعي؟ وما العلاقة بين  النظام السياسي والبناء الاجتماعي ؟\\n', 0, 0, NULL, NULL, '2022-03-08 05:22:44', '2022-03-08 05:22:44'),
(233878, 181, 215, 'لا يهدف التسوق الذكي إلى حرمانك من متعة الحصول على الأشياء بين الحين والآخر، لكن المراد هو أن يكون لعملية التسوق مردود إيجابي وسد احتياجات الأسرة الأس', 'لا يهدف التسوق الذكي إلى حرمانك من متعة الحصول على الأشياء بين الحين والآخر، لكن المراد هو أن يكون لعملية التسوق مردود إيجابي وسد احتياجات الأسرة الأساسية وذلك في حدود الميزانية الموضوعة. فاتباع نموذج التسوق الذكي يضمن لك الحفاظ على الميزانية الشهرية وتوفير جزء كبير من الراتب.\\nما  هي أسباب إنفاق جزء كبير من الراتب خلال عملية التسوق؟ و ماهي خطوات التسوق الذكي؟ وما هي فوائده ؟\\n', 0, 0, NULL, NULL, '2022-03-09 06:53:16', '2022-03-09 06:53:16'),
(233879, 181, 215, 'وجد علماء الاجتماع إنه يمكن لاستراتيجية الابتكار أن تساعد في مواجهة التحديات الاجتماعية المختلفة ،  قد لا يتمتع الأفراد والجماعات في المجتمع بالمساواة', 'وجد علماء الاجتماع إنه يمكن لاستراتيجية الابتكار أن تساعد في مواجهة التحديات الاجتماعية المختلفة ،  قد لا يتمتع الأفراد والجماعات في المجتمع بالمساواة في الوصول إلى الحقوق أو الفرص مثل: التوظيف أو الموارد مثل الرعاية الصحية والتعليم، وقد تشمل هذه المشكلة الشباب أو كبار السن أو الأشخاص ذوي الإعاقة أو المهاجرين أو فئات اجتماعية معينة أو العاطلين عن العمل، وهذا الاستبعاد يمنع الأفراد والجماعات من المساهمة في الحياة الاقتصادية والاجتماعية والسياسية لمجتمعهم، ويمكن أن يؤدي إلى توترات اجتماعية وصراعات ويؤثر سلباً على التنمية الاقتصادية.\\nكيف تؤثر التفاوتات والاختلافات في مستويات المعيشة بين المجموعات في المجتمع؟ وكيف نطبق استراتيجية محددة لمعالجة المشاكل والعقبات الاجتماعية ؟\\n', 0, 0, NULL, NULL, '2022-03-09 06:54:46', '2022-03-09 06:54:46'),
(233970, 181, 215, '\\nيوم السعادة العالمي يحتفل المجتمع الدولي في 20 مارس كيوم عالمي للسعادة بعد أن اعتمدت الأمم المتحدة في دورتها السادسة والستين هذا اليوم من كل عام يوم', '\\nيوم السعادة العالمي يحتفل المجتمع الدولي في 20 مارس كيوم عالمي للسعادة بعد أن اعتمدت الأمم المتحدة في دورتها السادسة والستين هذا اليوم من كل عام يوما دوليا للسعادة اعترافا بأهمية السعي للسعادة أثناء تحديد أطر السياسة العامة لتحقق التنمية المستدامة والقضاء على الفقر وتوفير الرفاهية لجميع الشعوب.\\nاليوم العالمي للسعادة هو يوم لممارسة التفكير الإيجابي أو لتقديم الشكر على الأشياء في حياتك التي تجعلك سعيدًا. لكنه في الواقع مشروع للأمم المتحدة له غرض أكثر جدية. تعتقد الأمم المتحدة أن السعادة لن تكون متاحة للجميع إلا عندما يتساوى شعوب العالم. تقيس الأمم المتحدة وتقارن السعادة في مختلف البلدان في تقرير السعادة العالمي. وهي تبني تقريرها على الرفاه الاجتماعي والاقتصادي والبيئي. تضع الأمم المتحدة أيضًا أهدافًا للدول لتحقيقها لزيادة السعادة لأنها تقول إن السعادة حق أساسي من حقوق الإنسان. لا ينبغي أن تكون السعادة شيئًا يمتلكه الناس لأنهم محظوظون للعيش في مكان تتوفر فيه الأشياء الأساسية مثل السلام والتعليم والحصول على الرعاية الصحية.\\nفي يوم السعادة العالمي هل  يشعر الشباب العربي بالسعادة؟\\n', 0, 0, NULL, NULL, '2022-03-12 10:08:33', '2022-03-12 10:08:33'),
(233971, 181, 215, 'يُعَدُّ العلم من أعظم أسباب السعادة، ومن أقوى عوامل الرقي بين الأمم والشعوب، فهو في الحياة سر نهضتها ورقيّها وتقدمها، بل هو عصب الحياة بامتياز، وهو عن', 'يُعَدُّ العلم من أعظم أسباب السعادة، ومن أقوى عوامل الرقي بين الأمم والشعوب، فهو في الحياة سر نهضتها ورقيّها وتقدمها، بل هو عصب الحياة بامتياز، وهو عنوان الأمم الراقية، وذلك متى قام على أسس سليمة، وغايات نبيلة، ومتى كان ميدانه تحقيق الخير وخدمة الإنسانية والرقي بين البشر، وإن كان خلاف ذلك فهو سبب بكل تأكيد في شقائها\\nالعلم أعظم شيء يفتخر به الإنسان فلذا لا يستوي أصحاب العلم وأصحاب الجهل\\nهل يعنى التفوق في الدراسة التفوق في العلم؟ \\n\\n', 0, 0, 'image', NULL, '2022-03-12 10:24:05', '2022-03-12 10:24:05'),
(234011, 181, 215, 'من أهم الأمور التي ينبغي اتباعها لإظهار الاحترام للآخرين ما يلي: الشعور بالامتنان. احترام القوانين واللوائح وعدم خرقهما. الاستماع إلى الآخرين. تقديم ا', 'من أهم الأمور التي ينبغي اتباعها لإظهار الاحترام للآخرين ما يلي: الشعور بالامتنان. احترام القوانين واللوائح وعدم خرقهما. الاستماع إلى الآخرين. تقديم المساعدة للآخرين عند امتلاك القدرة على ذلك. الاهتمام بالبيئة وبالأماكن المشتركة. التعاطف مع الآخرين وفهم مشاعرهم. احترام مساحة الآخرين الشخصية. الحفاظ على أسرار الآخرين. التواصل مع الآخرين بشكلٍ صارم، وهذا يعني الدفاع عن الحقوق الخاصة جنباً إلى جنب مع احترام حقوق الآخرين، بطريقة متروية وغير عدوانية. احترام ممتلكات الآخرين وعدم استخدامها إلا بعد الاستئذان. الاهتمام بالآخرين. التيقُّن بأن الأفكار والمرجعيات تختلف من شخص لآخر وهذا لا يعني أن يكون أحد الأشخاص على خطأ. الاعتذار للآخرين عند الخطأ في حقهم. احترام الذات يبدأ احترام الآخرين باحترام الذات أولاً، إذ لا يستطيع الشخص احترام الآخرين وهو لا يُكن الاحترام لنفسه، ومن أهم أساسيات احترام الذات ما يلي: وضع أهداف مهمة ومحاولة تحقيقها، وعند تحقيق أهداف أكثر يزداد احترام الذات أكثر. الصدق والأمانة مع الذات ومع الآخرين. فهم قيمة الأخلاق الحميدة والسلوكيات المناسبة مما يولد الرضا عن النفس واحترام الآخرين. معرفة الصديق الذي يؤثر بشكل إيجابي والتمسك به، والصديق الذي يؤثر بشكل سلبي ومحاولة الابتعاد عنه. الاستماع للآخرين واحترام معتقداتهم. كيفية احترام الطرف الآخر في العلاقات ينبغي أن يحترم الطرفين الآخر؛ لتزدهر العلاقة وتثمر، ونذكر هنا بعض النقاط التي من شأنها تعزيز مستوى الاحترام بين الطرفين: التعبير للطرف الآخر عن مدى السعادة به وبالعلاقة معه. التخلص من جميع حركات الاحتقار مهما كانت بسيطة. الاستماع بانتباه إلى احتياجات الطرف الآخر ورغباته واهتماماته. إظهار الاحترام للطرف الآخر أمام الآخرين. الاستجابة لطلبات الطرف الآخر في نفس الوقت بدون تأجيل. تقديم الاعتذار عند القيام بشيء خاطئ. التعاطف مع الطرف الآخر عند قيامه بشيء خاطئ. التحدث بشكل مباشر مع الطرف الآخر بدلاً من الشكوى منه للآخرين. التحدث بطريقة لطيفة مع الطرف الآخر بدلاً من السخرية. دعم آراء وأفكار الطرف الآخر.\\n\\nما هي أساليبك التي تستخدمها لإبداء احترامك للآخرين؟\\n', 0, 0, 'image', NULL, '2022-03-14 17:06:54', '2022-03-14 17:06:54'),
